  "data": [
    {
      "name": "cv",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "vuln_cve"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "snap": {
                  "terms": {
                    "field": "data.cortex.snapshot_id",
                    "size": 1,
                    "order": {
                      "_key": "desc"
                    }
                  },
                  "aggs": {
                    "crit": {
                      "filter": {
                        "term": {
                          "data.cortex.severity": "critical"
                        }
                      }
                    },
                    "high": {
                      "filter": {
                        "term": {
                          "data.cortex.severity": "high"
                        }
                      }
                    },
                    "inst": {
                      "sum": {
                        "script": {
                          "source": "if (!doc.containsKey(params.f) || doc[params.f].size() == 0) return 0;def v = doc[params.f].value;return v instanceof Number ? ((Number) v).doubleValue() : Double.parseDouble(v.toString());",
                          "lang": "painless",
                          "params": {
                            "f": "data.cortex.affected_hosts_count"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.snap.buckets"
      }
    },
    {
      "name": "ep",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "vuln_endpoint"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "snap": {
                  "terms": {
                    "field": "data.cortex.snapshot_id",
                    "size": 1,
                    "order": {
                      "_key": "desc"
                    }
                  },
                  "aggs": {
                    "vuln": {
                      "filter": {
                        "terms": {
                          "data.cortex.severity": [
                            "critical",
                            "high",
                            "medium",
                            "low"
                          ]
                        }
                      }
                    },
                    "crit": {
                      "filter": {
                        "term": {
                          "data.cortex.severity": "critical"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.snap.buckets"
      }
    },
    {
      "name": "tiles",
      "values": [
        {
          "i": 0,
          "label": "CVEs",
          "bad": false
        },
        {
          "i": 1,
          "label": "Critical CVEs",
          "bad": true
        },
        {
          "i": 2,
          "label": "High CVEs",
          "bad": true
        },
        {
          "i": 3,
          "label": "Vulnerability instances",
          "bad": false
        },
        {
          "i": 4,
          "label": "Vulnerable endpoints",
          "bad": true
        },
        {
          "i": 5,
          "label": "Critical endpoints",
          "bad": true
        }
      ],
      "transform": [
        {
          "type": "formula",
          "expr": "datum.i === 0 ? (length(data('cv')) ? data('cv')[0].doc_count : 0) : datum.i === 1 ? (length(data('cv')) ? data('cv')[0].crit.doc_count : 0) : datum.i === 2 ? (length(data('cv')) ? data('cv')[0].high.doc_count : 0) : datum.i === 3 ? (length(data('cv')) ? data('cv')[0].inst.value : 0) : datum.i === 4 ? (length(data('ep')) ? data('ep')[0].vuln.doc_count : 0) : datum.i === 5 ? (length(data('ep')) ? data('ep')[0].crit.doc_count : 0) : 0",
          "as": "value"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.46"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "max(14, min(height * 0.42, width / 6 * 0.26))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.bad && datum.value > 0 ? '#BD271E' : '#343741'"
          },
          "text": {
            "signal": "isString(datum.value) ? datum.value : format(datum.value, ',')"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.82"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
