}"}}

{"title": "Cortex XDR vulnerabilities - CVEs by severity", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.integration": "cortex_xdr"
                    }
                  },
                  {
                    "term": {
                      "data.cortex.event_type": "vuln_cve"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "snap": {
                "terms": {
                  "field": "data.cortex.snapshot_id",
                  "size": 1,
                  "order": {
                    "_key": "desc"
                  }
                },
                "aggs": {
                  "b": {
                    "terms": {
                      "field": "data.cortex.severity",
                      "size": 10
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.snap.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "b.buckets"
      ],
      "as": [
        "b"
      ]
    },
    {
      "calculate": "indexof([\"critical\", \"high\", \"medium\", \"low\", \"none\"], datum.b.key) >= 0 ? datum.b.key : 'other'",
      "as": "cat"
    },
    {
      "calculate": "datum.b.doc_count",
      "as": "n"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "n"
        }
      ],
      "groupby": [
        "cat"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "total"
        }
      ]
    },
    {
      "calculate": "datum.n / datum.total",
      "as": "pct"
    },
    {
      "calculate": "({\"critical\": \"#BD271E\", \"high\": \"#E7664C\", \"medium\": \"#D6BF57\", \"low\": \"#54B399\", \"none\": \"#98A2B3\", \"other\": \"#D3DAE6\"})[datum.cat] || '#D3DAE6'",
      "as": "cat_hex"
    },
    {
      "calculate": "indexof([\"critical\", \"high\", \"medium\", \"low\", \"none\", \"other\"], datum.cat)",
      "as": "cat_ord"
    },
    {
      "calculate": "(datum.cat_ord < 10 ? '0' : '') + datum.cat_ord + ' ' + datum.cat",
      "as": "cat_key"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "arc",
        "innerRadius": {
          "expr": "min(width, height) * 0.25"
        },
        "outerRadius": {
          "expr": "min(width, height) * 0.47"
        },
        "stroke": "#fff",
        "strokeWidth": 1.5,
        "cornerRadius": 2
      },
      "encoding": {
        "theta": {
          "field": "n",
          "type": "quantitative",
          "stack": true
        },
        "order": {
          "field": "n",
          "sort": "descending"
        },
        "color": {
          "field": "cat_key",
          "type": "nominal",
          "title": null,
          "legend": {
            "orient": "right",
            "labelLimit": 180,
            "symbolType": "circle",
            "labelExpr": "slice(datum.label, 3)"
          },
          "scale": {
            "range": {
              "field": "cat_hex"
            }
          }
        },
        "tooltip": [
          {
            "field": "cat",
            "title": "Value"
          },
          {
            "field": "n",
            "title": "Count"
          },
          {
            "field": "pct",
            "title": "Share",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "radius": {
          "expr": "min(width, height) * 0.36"
        },
        "fontSize": 11,
        "fontWeight": "bold",
        "fill": "#fff"
      },
      "encoding": {
        "theta": {
          "field": "n",
          "type": "quantitative",
          "stack": true
        },
        "order": {
          "field": "n",
          "sort": "descending"
        },
        "text": {
          "condition": {
            "test": "datum.pct >= 0.06",
            "field": "n",
            "type": "quantitative"
          },
          "value": ""
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "n",
              "as": "t"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 26,
        "fontWeight": "bold",
        "fill": "#343741",
        "dy": -7
      },
      "encoding": {
        "text": {
          "field": "t",
          "type": "quantitative",
          "format": ","
        },
        "x": {
          "value": {
            "expr": "width / 2"
          }
        },
        "y": {
          "value": {
            "expr": "height / 2"
          }
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "k"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 11,
        "fill": "#69707D",
        "dy": 13,
        "text": "CVEs"
      },
      "encoding": {
        "x": {
          "value": {
            "expr": "width / 2"
          }
        },
        "y": {
          "value": {
            "expr": "height / 2"
          }
        }
      }
    }
  ],
  "view": {
    "stroke": null
  }
}"}}

